{
  "hypotheses": [
    {
      "id": "H1",
      "mechanism": "Dynamic similarity mismatch: the transferred controller's frequency, gains, and ramp are not scaled for the longer legs and lower mass, causing excessive step frequency and insufficient step length.",
      "evidence": [
        "creature.features.L",
        "creature.reference.features.L",
        "baseline.controller_freq_ratio",
        "baseline.step_freq_hz",
        "baseline.step_length_over_leg",
        "baseline.capture_margin_over_leg_mean"
      ],
      "competing": [
        "The stride amplitudes (hip_amp, knee_amp) are not suited for the longer legs."
      ]
    },
    {
      "id": "H2",
      "mechanism": "Insufficient torque authority: tau_ratio = 0.61 is much lower than reference 0.995, causing hip and ankle torque saturation and inability to generate sufficient push-off.",
      "evidence": [
        "creature.features.tau_ratio",
        "creature.reference.features.tau_ratio",
        "baseline.peak_tau_over_limit_hip",
        "baseline.peak_tau_over_limit_ankle"
      ],
      "competing": [
        "The feedback gains (kp, kd, balance_gain) are too high, causing excessive torque demands."
      ]
    },
    {
      "id": "H3",
      "mechanism": "Missing foot placement feedback: the placement gains fp_kd and fp_kv are zero, so the controller cannot adjust foot placement based on torso velocity and distance, resulting in foot landing behind the capture point and progressive rearward foot placement trend.",
      "evidence": [
        "baseline.capture_margin_over_leg_mean",
        "baseline.touchdown_foot_ahead_over_leg_mean",
        "baseline.touchdown_foot_ahead_trend"
      ],
      "competing": [
        "The stride parameters (hip_amp, knee_amp, ramp_s) determine the nominal foot placement and are not suited for the current body."
      ]
    }
  ],
  "probes": [
    {
      "probe_id": "similarity",
      "hypothesis": "H1",
      "expect": "improves"
    },
    {
      "probe_id": "torque_x1_5",
      "hypothesis": "H2",
      "expect": "improves"
    },
    {
      "probe_id": "opt_placement",
      "hypothesis": "H3",
      "expect": "improves"
    }
  ]
}

